#!/usr/bin/env bash
# Final assessment S10 (unseen scenario: no hints in this file) — break/fix injector.
# Run: WSL host, kind lab-plain with MetalLB installed (lab 4.02 setup; unset KUBECONFIG first)
# Rebuilds the lab's starting state, injects one fault, prints the ticket.
# The payload is base64 so a glance at this file does not spoil the
# challenge. The fix: ../../reveal.sh S10, only once it is scored.
set -euo pipefail
export LAB_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
export PHASE_DIR="$(cd "$LAB_DIR/../.." && pwd)"
export WB_DIR="$(cd "$PHASE_DIR/.." && pwd)"
P=''
base64 -d <<<"$P" | bash -s -- "$@"
